import re

def add_import(content, search, add):
    if add in content:
        return content
    if search in content:
        return content.replace(search, search + '\n' + add)
    # Fallback to after the last from django... import
    lines = content.split('\n')
    for i in range(len(lines) - 1, -1, -1):
        if lines[i].startswith('from django'):
            lines.insert(i + 1, add)
            return '\n'.join(lines)
    return add + '\n' + content

def update_expressions():
    with open('django/db/models/expressions.py', 'r') as f:
        content = f.read()
    classes_to_decorate = [
        'Expression', 'Func', 'Value', 'ExpressionList', 'ExpressionWrapper',
        'When', 'Case', 'Subquery', 'Exists', 'OrderBy', 'OuterRef',
        'Window', 'WindowFrame', 'RowRange', 'ValueRange'
    ]
    for cls in classes_to_decorate:
        if cls == 'Expression':
            content = content.replace('@deconstructible\nclass Expression', "@deconstructible(path='django.db.models.Expression')\nclass Expression")
        else:
            pattern = rf'class {cls}\((.*?)\):'
            prefix = "@deconstructible(path='django.db.models." + cls + "')\n"
            replacement = prefix + r"class " + cls + r"(\1):"
            if f"@deconstructible(path='django.db.models.{cls}')" not in content:
                content = re.sub(pattern, replacement, content)
    with open('django/db/models/expressions.py', 'w') as f:
        f.write(content)

